#!/usr/bin/env python3
"""Separate scoped audit of FRESH12 existing artefacts; never generates or scores text."""
import base64,csv,hashlib,hmac,io,json,re,sys,zlib
from pathlib import Path
from collections import Counter
from cryptography.hazmat.primitives.ciphers.aead import AESGCM
P=Path('/mnt/data/ttm_fresh12_executor_private')
sys.path.insert(0,str(P));from ttm_tokenizer_private import BPE2048
sha=lambda x:hashlib.sha256(x).hexdigest()
read=lambda name:(P/name).read_bytes()
checks={}
def ck(name,condition):
 checks[name]=bool(condition)
 if not condition:raise AssertionError('FAILED_'+name)
raw=json.loads(read('FRESH12_PRIVATE_RAW_48_UNADJUDICATED.json'))
claim=json.loads(read('FRESH12_SINGLE_BATCH_CLAIM.json'))
blind=json.loads(read('FRESH12_BLINDED_REVIEWER_PACKET.json'))
map_private=json.loads(read('FRESH12_PRIVATE_MAPPING.json'))
qa=json.loads(read('FRESH12_PACKET_QA_PUBLIC.json'))
prompts=json.loads(read('prompts.json'))
ck('claim_source_hashed',sha(read('FRESH12_SINGLE_BATCH_CLAIM.json'))==raw['claim_sha256']==qa['raw_claim_sha256'])
ck('raw_count_48',raw['n_generations']==48==len(raw['results']))
ck('source_locked_prereg',claim['frozen_prereg_git_blob']=='919c43f2c919fa733b20a9be5d6b965e9649339c')
ck('amendment_before_claim',claim['pre_run_amendment_commit']=='cf0b11db6862c16bfe4a8690c6137a92f1d67a3b')
ck('greedy_only',all(x['decoder']=='greedy_argmax' for x in raw['results']))
ck('no_extra_prompts',set(x['prompt_id'] for x in raw['results'])==set(p['id'] for p in prompts))
ck('one_each_combination',len({(x['prompt_id'],x['checkpoint_step'],x['condition']) for x in raw['results']})==48)
ck('source_sha_bpe',raw['token_merges_sha256']=='aea0e2a1a1bc1943f20b767ba2f879e3a47f0cb43b8b66026b1a34a038e014af')
bpe=BPE2048(P/'bpe_pairs.b64')
ck('prompt_text_roundtrip',all(bpe.decode(bpe.encode(p['text']))==p['text'] for p in prompts))
ck('prompt_source_sha',all(sha(p['text'].encode())==p['sha256'] for p in prompts))
ck('serialized_one_byte_suffix',all(x['prompt_token_ids']==bpe.encode(x['prompt_clean']+(' ' if x['condition']=='BASELINE_FINAL_ASCII_SPACE' else '')) for x in raw['results']))
ck('pair_seed_pinned',all(x['seed']==20261109+int(x['prompt_id'][1:]) for x in raw['results']))
ck('generated_BPE_ID_valid',all(all(i!=256 and 0<=i<2048 for i in x['generated_token_ids']) for x in raw['results']))
ck('generation_length_stop',all(x['generated_token_count']==len(x['generated_token_ids'])<=64 and (len(x['generated_token_ids'])==64 or x['stop_reason']=='eos') for x in raw['results']))
ck('generation_decode_verbatim',all(bpe.decode(x['generated_token_ids'])==x['generated_text'] and sha(x['generated_text'].encode())==x['generated_text_sha256'] for x in raw['results']))
ck('raw_sha_source',sha(read('FRESH12_PRIVATE_RAW_48_UNADJUDICATED.json'))==qa['source_raw_sha256'])
ck('blind_pair_count',len(blind['pairs'])==24 and blind['n_pairs']==24 and blind['n_texts']==48)
ck('blind_unique_ids',set(x['pair_id'] for x in blind['pairs'])=={f'R{i:02d}' for i in range(1,25)})
ck('mapping_pair_count',len(map_private['mapping'])==24 and set(x['pair_id'] for x in map_private['mapping'])==set(x['pair_id'] for x in blind['pairs']))
owner=json.load(open('/mnt/data/TTM_FRESH12_OWNER_PRIVATE_DECRYPTION_KEY_DO_NOT_GITHUB.json'))
key=bytes.fromhex(owner['key_hex'])
seed=AESGCM(key).decrypt(base64.b64decode('FJHA1Ku4+8oBMCgf'),base64.b64decode('caKCwszdf8TQwvLi3JP6Vb1nt8xFBxxxeIqn4whjbtz+r8O2T9ntjS27w9W5JNuZ'),b'TTM_SMALL4M_FRESH12_A_B_ALLOCATION_SEED_V1')
ck('escrow_seed_commitment',sha(seed)=='5efcfa520f604d21d96fb62d27987003c21fe991c51d5974cd6ff24a64ddc4c4')
trim_set=set(sorted((p['id'] for p in prompts),key=lambda pid:hmac.new(seed,b'BALANCE:'+pid.encode(),hashlib.sha256).digest())[:6])
ck('AB_12_12_balance',sum(m['A_condition']=='TRIMMED_NO_TRAILING_ASCII_SPACE' for m in map_private['mapping'])==12)
ck('AB_6_6_each_checkpoint',all(sum(m['A_condition']=='TRIMMED_NO_TRAILING_ASCII_SPACE' and m['checkpoint_step']==st for m in map_private['mapping'])==6 for st in (1024,1280)))
ck('AB_map_algorithm',all((m['A_condition']=='TRIMMED_NO_TRAILING_ASCII_SPACE')==((m['prompt_id'] in trim_set) if m['checkpoint_step']==1024 else (m['prompt_id'] not in trim_set)) for m in map_private['mapping']))
order=sorted(((p['id'],st) for p in prompts for st in (1024,1280)),key=lambda x:hmac.new(seed,('PACKET_ORDER_V1|'+x[0]+'|'+str(x[1])).encode(),hashlib.sha256).digest())
ck('opaque_pair_order_frozen_HMAC',all((m['prompt_id'],m['checkpoint_step'])==order[i] for i,m in enumerate(map_private['mapping'])))
lookup={(r['prompt_id'],r['checkpoint_step'],r['condition']):r for r in raw['results']}
mp={x['pair_id']:x for x in map_private['mapping']}
ck('paired_display_exact_source',all(r['output_A']==lookup[(mp[r['pair_id']]['prompt_id'],mp[r['pair_id']]['checkpoint_step'],mp[r['pair_id']]['A_condition'])]['generated_text'].lstrip(' \t\r\n') and r['output_B']==lookup[(mp[r['pair_id']]['prompt_id'],mp[r['pair_id']]['checkpoint_step'],mp[r['pair_id']]['B_condition'])]['generated_text'].lstrip(' \t\r\n') for r in blind['pairs']))
ck('paired_prompts_exact',all(r['prompt']==next(p['text'] for p in prompts if p['id']==mp[r['pair_id']]['prompt_id']) for r in blind['pairs']))
packet_md=read('FRESH12_BLINDED_REVIEWER_PACKET.md').decode()
ck('markdown_all_24_and_48',len(re.findall(r'^## R\d\d$',packet_md,flags=re.M))==24 and packet_md.count('~~~text')==48)
ck('no_sensitive_column_labels',not re.search(r'F\d\d-C(?:1024|1280)|BASELINE_FINAL_ASCII_SPACE|TRIMMED_NO_TRAILING_ASCII_SPACE|checkpoint_step|prompt_token_ids|generated_token_ids',packet_md+read('FRESH12_REVIEWER_SCORE_TEMPLATE_R01_R24.csv').decode()))
with io.StringIO(read('FRESH12_REVIEWER_SCORE_TEMPLATE_R01_R24.csv').decode()) as f:csvrows=list(csv.DictReader(f))
ck('score_template_complete_empty_144',len(csvrows)==24 and all(r['pair_id']==f'R{i:02d}' and all(r[k]=='' for k in ['A_adherence','A_coherence','A_consistency','B_adherence','B_coherence','B_consistency']) for i,r in enumerate(csvrows,1)))
ck('packet_sha_matches_manifest',sha(read('FRESH12_BLINDED_REVIEWER_PACKET.json'))==qa['reviewer_packet_json_sha256'] and sha(read('FRESH12_BLINDED_REVIEWER_PACKET.md'))==qa['reviewer_packet_md_sha256'])
ck('template_sha_matches_manifest',sha(read('FRESH12_REVIEWER_SCORE_TEMPLATE_R01_R24.csv'))==qa['reviewer_score_template_sha256'])
enc=json.loads(read('FRESH12_ENCRYPTED_RAW_AND_MAPPING.json'))
plaintext=zlib.decompress(AESGCM(key).decrypt(base64.b64decode(enc['nonce_b64']),base64.b64decode(enc['ciphertext_with_tag_b64']),enc['aad_utf8'].encode()))
inner=json.loads(plaintext)
ck('encrypted_raw_roundtrip',inner['raw']==raw and inner['mapping']==map_private['mapping'] and sha(plaintext)==enc['plaintext_uncompressed_sha256'])
ck('encrypted_raw_sha_public',sha(read('FRESH12_ENCRYPTED_RAW_AND_MAPPING.json'))==qa['encrypted_private_raw_mapping_sha256'])
ck('no_secret_key_in_ciphertext',owner['key_hex'] not in read('FRESH12_ENCRYPTED_RAW_AND_MAPPING.json').decode())
ck('unadjudicated_status',raw['status']=='EXECUTED_48_UNADJUDICATED' and qa['semantic_scores']==0)
ck('no_training_test_q1q2',raw['new_training_steps']==0 and raw['test_reads']==0 and raw['q1q2_reads']==0)
ck('governance_hold',qa['pr13_hold'] and qa['main_unchanged'] and qa['lineage_L0017_unchanged'])
assert all(checks.values())
receipt={'schema':'ttm.fresh12.material_audit.separate_source_v1','status':'PASS_'+str(len(checks))+'_OF_'+str(len(checks))+'_AUTHOR_SIDE_SEPARATE_TECHNICAL_AUDIT','checks':checks,'n_pairs':24,'n_generations':48,'n_rubric_scores':0,'reviewer_role':'ACCEPTED_SCOPED_CODEX_AI','independent_human_scoring':'NOT_PERFORMED','scope':'FROZEN_SOURCE_MATERIAL_ARITHMETIC_AND_CONFIDENTIALITY_ONLY_NOT_SCIENTIFIC_QUALITY','source_raw_sha256':sha(read('FRESH12_PRIVATE_RAW_48_UNADJUDICATED.json')),'packet_md_sha256':sha(read('FRESH12_BLINDED_REVIEWER_PACKET.md')),'reviewer_score_template_sha256':sha(read('FRESH12_REVIEWER_SCORE_TEMPLATE_R01_R24.csv')),'encrypted_custody_sha256':sha(read('FRESH12_ENCRYPTED_RAW_AND_MAPPING.json')),'no_training':True,'no_test':True,'no_q1q2':True,'no_unblind':True,'pr13_hold':True,'lineage_L0017_unchanged':True}
(P/'FRESH12_SEPARATE_MATERIAL_AUDIT.json').write_text(json.dumps(receipt,ensure_ascii=False,sort_keys=True,indent=2)+'\n')
print(receipt['status'])
print('INDEPENDENT_HUMAN_REVIEW=NOT_PERFORMED; SCORE=0/144')
print('SOURCE_RAW_SHA256='+receipt['source_raw_sha256'])
